package com.yeyamo_mobile.api.gamification_service.infrastructure.messaging;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.JsonNode;import com.yeyamo_mobile.api.gamification_service.domain.XpActivity;
@Component public class EventXpPolicy{public Optional<XpActivity>map(JsonNode e){String type=required(e,"eventType");JsonNode p=e.path("payload");UUID event=UUID.fromString(required(e,"eventId"));Instant occurred=instant(e,"occurredAt");return switch(type){case"profile.created"->activity(event,required(p,"authUserId"),25,"PROFILE_CREATED",required(p,"profileId"),"PROFILE",null,occurred);case"content.post.published"->activity(event,required(p,"authorId"),20,"POST_PUBLISHED",required(p,"postId"),"POST",null,occurred);case"interaction.like.added"->activity(event,required(p,"userId"),2,"LIKE",required(p,"postId"),"SOCIAL",null,occurred);case"interaction.favorite.added"->activity(event,required(p,"userId"),3,"FAVORITE",required(p,"postId"),"SOCIAL",null,occurred);case"interaction.comment.created"->activity(event,required(p,"authorId"),5,"COMMENT",required(p,"commentId"),"SOCIAL",null,occurred);case"interaction.post.shared"->activity(event,required(p,"userId"),5,"SHARE",required(p,"shareId"),"SOCIAL",null,occurred);case"interaction.checkin.created"->activity(event,required(p,"userId"),30,"CHECKIN",required(p,"checkInId"),"CHECKIN",required(p,"catalogAssetId"),occurred);case"booking.confirmed","booking.completed"->activity(event,required(p,"userId"),50,"BOOKING",required(p,"bookingId"),"BOOKING",text(p,"catalogAssetId"),occurred);default->Optional.empty();};}private Optional<XpActivity>activity(UUID e,String u,int points,String reason,String source,String counter,String destination,Instant at){return Optional.of(new XpActivity(e,u,points,reason,source,counter,destination,at));}private String required(JsonNode n,String f){String v=text(n,f);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String text(JsonNode n,String f){JsonNode v=n.get(f);return v==null||v.isNull()?null:v.asText();}private Instant instant(JsonNode n,String f){try{String v=text(n,f);return v==null?Instant.now():Instant.parse(v);}catch(Exception e){return Instant.now();}}}
